def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We use the identity for a cap sphere tangent to a ring of N spheres (each of radius R) on a plane:
# r_cap = R / (4 sin^2(pi/N)). For N in {5,8,10,12}, 4 sin^2(pi/N) has a simple quadratic surd form,
# giving r_cap = a + b*sqrt(c) with square-free c.
# We choose inner_count in {5,8,10,12} and an inner_radius that ensures integer a,b.

counts = [5, 8, 10, 12]
inner_count = rng.choice(counts)

# Choose inner_radius with divisibility constraints so that a,b are integers
if inner_count == 5:
    # r_cap = R*(1/2 + (1/10)*sqrt(5)); need R % 10 == 0
    candidates = [10 * k for k in range(2, 51)]  # 20..510
    inner_radius = rng.choice(candidates)
